<?php require 'inc.php'; $u=need(['artesano','admin']);chk();$a=row('SELECT * FROM artesanos WHERE usuario_id=?','i',$u['id']);
if(!$a&&$u['rol']=='admin'){q("INSERT INTO artesanos(nombre,estado,usuario_id) VALUES('Tienda AJOLOMEX','México',?)",'i',$u['id']);go('artesano.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['nuevo'])&&trim($_POST['nombre'])&&$_POST['precio']>0)q('INSERT INTO productos(artesano_id,categoria,nombre,descripcion,precio,stock,icono) VALUES(?,?,?,?,?,?,?)','iissdis',$a['id'],(int)$_POST['cat'],$_POST['nombre'],$_POST['desc'],$_POST['precio'],max(0,(int)$_POST['stock']),$_POST['icono']?:'🎁');
 if(isset($_POST['pid']))q('UPDATE productos SET stock=?,precio=? WHERE id=? AND artesano_id=?','idii',max(0,(int)$_POST['stock']),$_POST['precio'],(int)$_POST['pid'],$a['id']);
 go('artesano.php');}
$P=rows('SELECT * FROM productos WHERE artesano_id=? ORDER BY id DESC','i',$a['id']);
$V=rows("SELECT o.folio,o.estado,o.envio_nombre,d.nombre,d.cantidad FROM detalles_orden d JOIN ordenes o ON o.id=d.orden_id JOIN productos p ON p.id=d.producto_id WHERE p.artesano_id=? AND o.estado<>'pendiente' ORDER BY o.id DESC",'i',$a['id']);head('Mi tienda');?>
<h1><?=e($a['nombre'])?></h1><p class="mut">Panel del artesano: administra tus piezas y consulta lo vendido.</p>
<div class="card" style="margin-bottom:20px"><h3>Agregar producto</h3><form method="post"><?=field()?><input type="hidden" name="nuevo" value="1"><div class="row"><div><label>Nombre</label><input name="nombre" required></div><div><label>Categoría</label><select name="cat"><?php foreach(CATS as $i=>$c)echo "<option value='$i'>".e($c).'</option>';?></select></div></div><div class="row"><div><label>Precio (MXN)</label><input name="precio" type="number" step="0.01" min="1" required></div><div><label>Existencias</label><input name="stock" type="number" min="0" value="1"></div><div><label>Emoji</label><input name="icono" maxlength="4" placeholder="🎁"></div></div><label>Descripción</label><textarea name="desc" rows="2"></textarea><br><button class="btn">Publicar</button></form></div>
<div class="card sc" style="margin-bottom:20px"><h3>Mis productos</h3><table><?php foreach($P as $p):?><tr><td><?=e($p['icono'].' '.$p['nombre'])?></td><td colspan="2"><form method="post" style="display:flex;gap:6px"><?=field()?><input type="hidden" name="pid" value="<?=$p['id']?>"><input name="precio" type="number" step="0.01" value="<?=$p['precio']?>" style="width:110px"><input name="stock" type="number" value="<?=$p['stock']?>" style="width:90px"><button class="btn s">Guardar</button></form></td></tr><?php endforeach;?></table></div>
<div class="card sc"><h3>Piezas vendidas</h3><table><?php foreach($V as $v)echo '<tr><td>'.e($v['folio']).'</td><td>'.e($v['nombre']).' × '.$v['cantidad'].'</td><td>'.e($v['envio_nombre']).'</td><td><span class="tag">'.ETQ[$v['estado']].'</span></td></tr>';if(!$V)echo '<tr><td class="mut">Aún no hay ventas.</td></tr>';?></table></div><?php foot();
